import{_ as e,o as r,c as t,ae as l}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"환율","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ko/guide/05-exchange-rate-guide.md","filePath":"v1/ko/guide/05-exchange-rate-guide.md"}'),i={name:"v1/ko/guide/05-exchange-rate-guide.md"};function o(h,a,n,d,s,u){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="환율" tabindex="-1">환율 <a class="header-anchor" href="#환율" aria-label="Permalink to &quot;환율&quot;">​</a></h1><h2 id="📋-개요" tabindex="-1">📋 개요 <a class="header-anchor" href="#📋-개요" aria-label="Permalink to &quot;📋 개요&quot;">​</a></h2><p>코알라 가계부는 다중 통화 기록을 지원하며, 환율 조회와 통화 전환 기능을 제공합니다.</p><hr><h2 id="💰-기준-통화-본위-통화" tabindex="-1">💰 기준 통화(본위 통화) <a class="header-anchor" href="#💰-기준-통화-본위-통화" aria-label="Permalink to &quot;💰 기준 통화(본위 통화)&quot;">​</a></h2><p>장부의 기본 통화로, 금액 표시와 통계 계산의 기준이 됩니다.</p><p>사용되는 곳:</p><ul><li>앱 전반의 금액 표시 기준</li><li>개요/통계 계산 기준</li><li>환율 목록에서 기준 통화 대비 환율 표시</li></ul><h2 id="🚀-변경-방법" tabindex="-1">🚀 변경 방법 <a class="header-anchor" href="#🚀-변경-방법" aria-label="Permalink to &quot;🚀 변경 방법&quot;">​</a></h2><ul><li>설정 → 통화 설정 → 기준 통화</li><li>장부 관리 → 장부 상세 → 장부 통화</li></ul><p>변경 후에는 표시/통계가 자동으로 갱신됩니다.</p><hr><h2 id="📊-환율-목록" tabindex="-1">📊 환율 목록 <a class="header-anchor" href="#📊-환율-목록" aria-label="Permalink to &quot;📊 환율 목록&quot;">​</a></h2><ul><li>지원 통화 목록을 확인할 수 있습니다</li><li>기준 통화 대비 환율을 볼 수 있습니다</li><li>우측 상단의 새로고침 버튼으로 최신 환율을 가져올 수 있습니다</li></ul><blockquote><p>💡 팁: 오프라인 상태에서는 최근 환율(캐시)을 사용할 수 있습니다.</p></blockquote><h2 id="💱-표시-규칙" tabindex="-1">💱 표시 규칙 <a class="header-anchor" href="#💱-표시-규칙" aria-label="Permalink to &quot;💱 표시 규칙&quot;">​</a></h2><p>환산 표시는 <strong>현재 환율</strong>을 사용합니다. 환율을 새로 고치거나 기준 통화를 바꾸면, 과거 내역의 환산 표시가 달라질 수 있습니다(원거래 금액은 변하지 않습니다).</p><hr><h2 id="🔄-캐시" tabindex="-1">🔄 캐시 <a class="header-anchor" href="#🔄-캐시" aria-label="Permalink to &quot;🔄 캐시&quot;">​</a></h2><p>코알라 가계부는 성능을 위해 환율을 앱 내부에 일시적으로 저장합니다.</p><ul><li>수동 새로고침, 기준 통화 변경, 장부 통화 변경 시 환율이 갱신됩니다</li></ul><hr><h2 id="⚙️-환율-수동-수정" tabindex="-1">⚙️ 환율 수동 수정 <a class="header-anchor" href="#⚙️-환율-수동-수정" aria-label="Permalink to &quot;⚙️ 환율 수동 수정&quot;">​</a></h2><p>일부 경우 환율 설정 화면에서 환율을 직접 입력해 저장할 수 있습니다. 저장한 값은 표시와 계산에 반영됩니다.</p><hr><h2 id="🔧-자주-묻는-질문" tabindex="-1">🔧 자주 묻는 질문 <a class="header-anchor" href="#🔧-자주-묻는-질문" aria-label="Permalink to &quot;🔧 자주 묻는 질문&quot;">​</a></h2><h3 id="q1-기준-통화를-바꾸면-과거-내역-금액이-바뀌나요" tabindex="-1">Q1: 기준 통화를 바꾸면 과거 내역 금액이 바뀌나요? <a class="header-anchor" href="#q1-기준-통화를-바꾸면-과거-내역-금액이-바뀌나요" aria-label="Permalink to &quot;Q1: 기준 통화를 바꾸면 과거 내역 금액이 바뀌나요?&quot;">​</a></h3><p>환산 “표시”는 달라질 수 있지만, <strong>원거래 금액은 변하지 않습니다</strong>.</p><h3 id="q2-환율이-이상해-보입니다" tabindex="-1">Q2: 환율이 이상해 보입니다 <a class="header-anchor" href="#q2-환율이-이상해-보입니다" aria-label="Permalink to &quot;Q2: 환율이 이상해 보입니다&quot;">​</a></h3><p>우측 상단 새로고침 버튼으로 환율을 업데이트해 보세요. 네트워크 환경에 따라 업데이트가 실패할 수 있습니다.</p><hr><p><strong>마지막 업데이트</strong>: 2026년 5월</p>',32)])])}const q=e(i,[["render",o]]);export{p as __pageData,q as default};
